16	/**
17	 * Credit a user's wallet for a completed Checkout session, idempotently.
18	 * Called from both the success-redirect confirm route (works without HTTPS)
19	 * and the webhook (belt-and-suspenders once HTTPS is available).
20	 * Returns true if a credit was applied this call.
21	 */
22	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
23	  const session = await stripe().checkout.sessions.retrieve(sessionId);
24	  const userId = session.metadata?.nxeonUserId;
25	  const cents = session.amount_total ?? 0;
26	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
27	
28	  const existing = await db.walletTransaction.findFirst({
29	    where: { description: { contains: session.id } },
30	  });
31	  if (existing) return false;
32	
33	  await db.$transaction([
34	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
35	    db.walletTransaction.create({
36	      data: { userId, amountCents: cents, description: `Stripe payment (${session.id})` },
37	    }),
38	    db.notification.create({
39	      data: {
40	        userId,
41	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
42	        href: "/dashboard/billing",
43	      },
44	    }),
45	  ]);
46	  // A funded wallet is the referred user's first paid action — reward both sides.
47	  try {
48	    const { maybeRewardReferral } = await import("./actions-growth");
49	    await maybeRewardReferral(userId);
50	  } catch { /* best-effort */ }
51	  try {
52	    const u = await db.user.findUnique({ where: { id: userId } });
53	    if (u) {
54	      const { sendMail, emails } = await import("./mailer");
55	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
56	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html });
57	    }
58	  } catch { /* best-effort */ }
59	  return true;
60	}
