import { requireArea } from "@/lib/rbac";
import { stripe, stripeConfigured } from "@/lib/stripe";

/**
 * Admin power-tools for finance ops: refunds, manual balance adjustments and
 * bulk invoice/client actions. Every action is gated by `requireArea("billing")`
 * (bulk-suspend is a clients-area capability and gates on "clients") and writes
 * an AuditLog row.
 *
 * The existing single-invoice void / mark-paid live in `lib/actions-billing.ts`;
 * we re-export them here so this module is the one finance-actions entry point
 * without duplicating their logic.
 */
export { voidInvoice, markInvoicePaid } from "@/lib/actions-billing";

async function audit(userId: string | null, action: string, detail?: string) {
  await db.auditLog.create({ data: { userId, action, detail } });
}

function parseAmountCents(raw: FormDataEntryValue | null): number | null {
  const amount = Number(raw);
  if (!Number.isFinite(amount) || amount === 0) return null;
  if (Math.abs(amount) > 50000) return null; // sanity cap: $50k / action
  return Math.round(amount * 100);
}

/** Pull a Stripe checkout-session id (cs_...) out of a wallet-transaction note. */
function sessionIdFrom(description: string | undefined | null): string | null {
  const m = (description ?? "").match(/cs_[A-Za-z0-9_]+/);
  return m ? m[0] : null;
}

/**
 * Refund a customer. When the top-up can be traced back to a Stripe Checkout
 * session (its wallet ledger row carries `Stripe payment (cs_...)`) and Stripe
 * is configured, the money is returned to the original card via the recovered
 * PaymentIntent. Otherwise we fall back to a **wallet-only** refund which simply
 * debits the wallet balance and records the ledger entry.
 *
 * Safety: the wallet is never driven below zero — for a wallet-only refund we
 * require sufficient balance; for a Stripe refund of already-spent funds we
 * decrement only what remains (the rest is a real-cash write-off) and note it.
 */
export async function refundPayment(
  _prev: unknown,
  formData: FormData
): Promise<{ error?: string; message?: string }> {
  const admin = await requireArea("billing");

  const userId = String(formData.get("userId") ?? "");
  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
  const cents = parseAmountCents(formData.get("amount"));

  if (!userId) return { error: "Missing customer." };
  if (cents === null || cents < 0) return { error: "Enter a positive refund amount (max $50,000)." };

  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) return { error: "Customer not found." };

  // --- Try to route the refund back to the original Stripe card ---
  let method: "stripe" | "wallet" = "wallet";
  let stripeRefundId: string | null = null;
  if (stripeConfigured()) {
    const tx = await db.walletTransaction.findFirst({
      where: { userId, description: { contains: "Stripe payment (cs_" } },
      orderBy: { createdAt: "desc" },
    });
    const sessionId = sessionIdFrom(tx?.description);
    if (sessionId) {
      try {
        const session = await stripe().checkout.sessions.retrieve(sessionId);
        const pi =
          typeof session.payment_intent === "string"
            ? session.payment_intent
            : session.payment_intent?.id;
        if (pi) {
          const refund = await stripe().refunds.create({ payment_intent: pi, amount: cents });
          stripeRefundId = refund.id;
          method = "stripe";
        }
      } catch {
        // Stripe refund failed / not refundable — fall back to wallet-only.
        method = "wallet";
      }
    }
  }

  const available = Math.max(0, user.balanceCents);
  const walletDebit = Math.min(cents, available);
  if (method === "wallet" && walletDebit < cents) {
    return {
      error:
        "Insufficient wallet balance for a wallet-only refund. Use a negative balance adjustment to force it.",
    };
  }

  const noteBits = [
    method === "stripe" ? `Stripe refund ${stripeRefundId}` : "wallet-only refund",
    reason,
  ].filter(Boolean);
  const description = `Refund — ${noteBits.join(" · ")}`;

  await db.$transaction(async (tx) => {
    if (walletDebit > 0) {
      await tx.user.update({
        where: { id: userId },
        data: { balanceCents: { decrement: walletDebit } },
      });
    }
    await tx.walletTransaction.create({
      data: { userId, amountCents: -cents, description },
    });
  });

  await audit(
    admin.id,
    "billing.refund",
    `user=${user.email} $${(cents / 100).toFixed(2)} via ${method}${
      stripeRefundId ? ` (${stripeRefundId})` : ""
    }`
  );
  revalidatePath("/admin/billing");
  revalidatePath(`/admin/users/${userId}`);
  revalidatePath("/dashboard/billing");

  const dollars = `$${(cents / 100).toFixed(2)}`;
  return {
    message:
      method === "stripe"
        ? `Refunded ${dollars} to the customer's card (Stripe ${stripeRefundId}).`
        : `Refunded ${dollars} to the wallet balance.`,
  };
}

/**
 * Manual +/- balance adjustment (credit or debit). A negative amount is the one
 * explicit case allowed to drive the balance below zero (e.g. clawing back a
 * mistaken credit); positive adjustments simply top the wallet up.
 */
export async function adjustBalance(
  _prev: unknown,
  formData: FormData
): Promise<{ error?: string; message?: string }> {
  const admin = await requireArea("billing");

  const userId = String(formData.get("userId") ?? "");
  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
  const cents = parseAmountCents(formData.get("amount"));

  if (!userId) return { error: "Missing customer." };
  if (cents === null) return { error: "Enter a non-zero amount (max ±$50,000)." };

  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) return { error: "Customer not found." };

  const description = `Admin balance adjustment${reason ? ` — ${reason}` : ""}`;
  await db.$transaction([
    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
    db.walletTransaction.create({ data: { userId, amountCents: cents, description } }),
  ]);

  await audit(
    admin.id,
    "billing.adjust_balance",
    `user=${user.email} ${cents >= 0 ? "+" : "−"}$${(Math.abs(cents) / 100).toFixed(2)}`
  );
  revalidatePath("/admin/billing");
  revalidatePath(`/admin/users/${userId}`);
  revalidatePath("/dashboard/billing");

  const dollars = `$${(Math.abs(cents) / 100).toFixed(2)}`;
  return { message: `${cents >= 0 ? "Credited" : "Debited"} ${dollars}. New balance applied.` };
}

/**
 * Bulk-void a set of open/unpaid invoices. Paid invoices are skipped (they must
 * be refunded instead) and already-void ones are ignored. Returns counts.
 */
export async function bulkVoidInvoices(
  ids: string[]
): Promise<{ voided: number; skipped: number }> {
  const admin = await requireArea("billing");
  const unique = [...new Set((ids ?? []).filter(Boolean))].slice(0, 500);
  if (unique.length === 0) return { voided: 0, skipped: 0 };

  const invoices = await db.invoice.findMany({ where: { id: { in: unique } } });
  const voidable = invoices.filter((i) => i.status === "OPEN" || i.status === "REFUNDED");

  if (voidable.length > 0) {
    await db.invoice.updateMany({
      where: { id: { in: voidable.map((i) => i.id) } },
      data: { status: "VOID", paidAt: null },
    });
  }

  await audit(admin.id, "billing.bulk_void", `${voidable.length} voided of ${unique.length}`);
  revalidatePath("/admin/invoices");
  revalidatePath("/dashboard/invoices");
  return { voided: voidable.length, skipped: unique.length - voidable.length };
}

/**
 * Bulk-suspend clients. Suspend is a clients-area capability, so this gates on
 * "clients" rather than "billing". The acting admin is never suspended.
 */
export async function bulkSuspendUsers(
  ids: string[]
): Promise<{ suspended: number }> {
  const admin = await requireArea("clients");
  const unique = [...new Set((ids ?? []).filter(Boolean))]
    .filter((id) => id !== admin.id)
    .slice(0, 500);
  if (unique.length === 0) return { suspended: 0 };

  const res = await db.user.updateMany({
    where: { id: { in: unique }, role: { not: "ADMIN" } },
    data: { suspended: true },
  });

  await audit(admin.id, "clients.bulk_suspend", `${res.count} suspended`);
  revalidatePath("/admin/users");
  return { suspended: res.count };
}

"use client";

import { useActionState } from "react";
import { refundPayment, adjustBalance } from "@/lib/actions-admin-billing";

type ActionState = { error?: string; message?: string };
const initial: ActionState = {};

function Notice({ state }: { state: ActionState }) {
  if (state.error)
    return <p className="text-xs font-medium text-red-400">{state.error}</p>;
  if (state.message)
    return <p className="text-xs font-medium text-emerald-400">{state.message}</p>;
  return null;
}

/**
 * Refund a customer. Routes back to the original Stripe card when the payment
 * can be traced, otherwise performs a wallet-only refund (see server action).
 */
export function RefundForm({
  userId,
  defaultAmount,
}: {
  userId: string;
  defaultAmount?: number;
}) {
  const [state, action, pending] = useActionState(refundPayment, initial);
  return (
    <form action={action} className="space-y-3">
      <input type="hidden" name="userId" value={userId} />
      <div className="flex flex-wrap items-end gap-2">
        <div>
          <label className="label">Amount (USD)</label>
          <input
            className="input w-32 py-1.5"
            name="amount"
            type="number"
            step="0.01"
            min="0.01"
            placeholder="0.00"
            defaultValue={defaultAmount != null ? (defaultAmount / 100).toFixed(2) : undefined}
            required
          />
        </div>
        <div className="flex-1 min-w-[180px]">
          <label className="label">Reason (optional)</label>
          <input className="input w-full py-1.5" name="reason" type="text" placeholder="Duplicate charge…" maxLength={200} />
        </div>
        <button className="btn-danger py-1.5" disabled={pending}>
          {pending ? "Refunding…" : "Refund"}
        </button>
      </div>
      <Notice state={state} />
      <p className="text-xs text-slate-500">
        Refunds the original Stripe card when the payment is traceable, otherwise credits back the wallet.
      </p>
    </form>
  );
}

/**
 * Manual +/- wallet balance adjustment. Positive credits, negative debits
 * (negative is the one case allowed to push a balance below zero).
 */
export function AdjustBalanceForm({ userId }: { userId: string }) {
  const [state, action, pending] = useActionState(adjustBalance, initial);
  return (
    <form action={action} className="space-y-3">
      <input type="hidden" name="userId" value={userId} />
      <div className="flex flex-wrap items-end gap-2">
        <div>
          <label className="label">Adjustment (USD)</label>
          <input
            className="input w-32 py-1.5"
            name="amount"
            type="number"
            step="0.01"
            placeholder="±0.00"
            required
          />
        </div>
        <div className="flex-1 min-w-[180px]">
          <label className="label">Reason (optional)</label>
          <input className="input w-full py-1.5" name="reason" type="text" placeholder="Goodwill credit…" maxLength={200} />
        </div>
        <button className="btn-secondary py-1.5" disabled={pending}>
          {pending ? "Applying…" : "Apply"}
        </button>
      </div>
      <Notice state={state} />
      <p className="text-xs text-slate-500">Use a negative amount to debit (e.g. clawing back a mistaken credit).</p>
    </form>
  );
}

/** Both finance tools grouped in one card body, bound to a single customer. */
export function RefundControls({
