"use client";

import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import type { ReactNode } from "react";

export type BulkColumn = { header: ReactNode; className?: string };
export type BulkRow = { id: string; cells: ReactNode[]; selectable?: boolean };
export type BulkAction = {
  label: string;
  /** Server action invoked with the selected row ids. */
  run: (ids: string[]) => Promise<unknown>;
  /** Confirmation prompt shown before running (skip when omitted). */
  confirm?: string;
  danger?: boolean;
};

/**
 * A self-contained, selectable admin table. The parent (a Server Component)
 * maps its data into `columns` + `rows` (cells may be arbitrary React nodes such
 * as <Link>s) and passes an `exportHref` and optional bulk `actions`. Selection
 * state, the select-all header checkbox and the floating action bar all live
 * here on the client; the export link points at the CSV route.
 */
export function BulkTable({
  columns,
  rows,
  exportHref,
  actions = [],
  minWidth = 720,
  empty = "Nothing to show.",
}: {
  columns: BulkColumn[];
  rows: BulkRow[];
  exportHref?: string;
  actions?: BulkAction[];
  minWidth?: number;
  empty?: string;
}) {
  const router = useRouter();
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);

  const selectableIds = useMemo(
    () => rows.filter((r) => r.selectable !== false).map((r) => r.id),
    [rows]
  );
  const allSelected = selectableIds.length > 0 && selectableIds.every((id) => selected.has(id));
  const someSelected = selected.size > 0;

  const toggle = (id: string) =>
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });

  const toggleAll = () =>
    setSelected(allSelected ? new Set() : new Set(selectableIds));

  const runAction = (action: BulkAction) => {
    if (action.confirm && !window.confirm(action.confirm)) return;
    const ids = [...selected];
    setMsg(null);
    start(async () => {
      try {
        await action.run(ids);
        setSelected(new Set());
        setMsg(`${action.label}: ${ids.length} row${ids.length === 1 ? "" : "s"} done.`);
        router.refresh();
      } catch (e) {
        setMsg(e instanceof Error ? e.message : "Action failed");
      }
    });
  };

  return (
    <div>
      {/* Action bar */}
      <div className="flex flex-wrap items-center justify-between gap-3 px-5 pt-5">
        <div className="flex items-center gap-3 text-sm text-slate-400">
          <span>
            {someSelected ? (
              <span className="font-medium text-slate-200">{selected.size} selected</span>
            ) : (
              `${rows.length} row${rows.length === 1 ? "" : "s"}`
            )}
          </span>
          {msg && <span className="text-xs text-slate-500">{msg}</span>}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {someSelected &&
            actions.map((a) => (
              <button
                key={a.label}
                className={`${a.danger ? "btn-danger" : "btn-secondary"} py-1.5`}
                disabled={pending}
                onClick={() => runAction(a)}
              >
                {a.label}
                <span className="ml-1 opacity-70">({selected.size})</span>
              </button>
            ))}
          {exportHref && (
            <a className="btn-secondary py-1.5" href={exportHref}>
              Export CSV
            </a>
          )}
        </div>
      </div>

      {rows.length === 0 ? (
        <p className="px-5 py-10 text-center text-sm text-slate-500">{empty}</p>
      ) : (
        <div className="overflow-x-auto pt-3">
          <table className="table-shell" style={{ minWidth }}>
            <thead>
              <tr>
                <th className="w-10">
                  <input
                    type="checkbox"
                    aria-label="Select all"
                    checked={allSelected}
                    onChange={toggleAll}
                    disabled={selectableIds.length === 0}
                  />
                </th>
                {columns.map((c, i) => (
                  <th key={i} className={c.className}>
                    {c.header}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => {
                const canSelect = row.selectable !== false;
                return (
                  <tr key={row.id} className={selected.has(row.id) ? "bg-white/[0.03]" : undefined}>
                    <td className="w-10">
                      <input
                        type="checkbox"
                        aria-label="Select row"
                        checked={selected.has(row.id)}
                        onChange={() => toggle(row.id)}
                        disabled={!canSelect}
                      />
                    </td>
                    {row.cells.map((cell, i) => (
                      <td key={i} className={columns[i]?.className}>
                        {cell}
                      </td>
                    ))}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { NextRequest, NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { db } from "@/lib/db";
import type { InvoiceStatus, Prisma } from "@prisma/client";

/**
 * RBAC-checked CSV export of the current (filtered) admin table.
 *
 *   /api/admin/export?type=users&q=…
 *   /api/admin/export?type=invoices&status=OPEN
 *
 * The filter params mirror the corresponding admin page so "Export CSV" always
 * reflects what the operator is looking at. Exports the full filtered set (not
 * just the current page). Never cached.
 */
export const dynamic = "force-dynamic";

function csvCell(v: unknown): string {
  const s = v == null ? "" : String(v);
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

function toCsv(headers: string[], rows: (string | number | null | undefined)[][]): string {
  const lines = [headers.map(csvCell).join(",")];
  for (const row of rows) lines.push(row.map(csvCell).join(","));
  return lines.join("\r\n");
}

function money(cents: number): string {
  return (cents / 100).toFixed(2);
}

const INVOICE_STATUSES: InvoiceStatus[] = ["OPEN", "PAID", "VOID", "REFUNDED"];

export async function GET(req: NextRequest) {
  const user = await realUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const sp = req.nextUrl.searchParams;
  const type = sp.get("type");
  const stamp = new Date().toISOString().slice(0, 10);

  if (type === "users") {
    if (!canAccess(user.role, "clients")) {
      return NextResponse.json({ error: "forbidden" }, { status: 403 });
    }
    const query = (sp.get("q") ?? "").trim();
    const where: Prisma.UserWhereInput = query
      ? {
          OR: [
            { email: { contains: query, mode: "insensitive" } },
            { name: { contains: query, mode: "insensitive" } },
          ],
        }
      : {};

    const users = await db.user.findMany({
      where,
      include: {
        servers: {
          where: { status: { notIn: ["DELETING"] } },
          select: { isFree: true, plan: { select: { priceCents: true } } },
        },
      },
      orderBy: { createdAt: "desc" },
    });

    const csv = toCsv(
      ["id", "name", "email", "role", "balance_usd", "mrr_usd", "servers", "suspended", "joined"],
      users.map((u) => {
        const mrr = u.servers.reduce((n, s) => n + (s.isFree ? 0 : s.plan.priceCents), 0);
        return [
          u.id,
          u.name,
          u.email,
          u.role,
          money(u.balanceCents),
          money(mrr),
          u.servers.length,
          u.suspended ? "yes" : "no",
          u.createdAt.toISOString(),
        ];
      })
    );

    return new NextResponse(csv, {
      status: 200,
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="nxeon-clients-${stamp}.csv"`,
        "Cache-Control": "private, no-store",
      },
    });
  }

  if (type === "invoices") {
    if (!canAccess(user.role, "billing")) {
      return NextResponse.json({ error: "forbidden" }, { status: 403 });
    }
    const statusParam = sp.get("status");
    const status = INVOICE_STATUSES.includes(statusParam as InvoiceStatus)
      ? (statusParam as InvoiceStatus)
      : undefined;

    const invoices = await db.invoice.findMany({
      where: status ? { status } : {},
      include: { user: { select: { email: true, name: true } } },
      orderBy: { createdAt: "desc" },
    });

    const csv = toCsv(
      ["number", "client_name", "client_email", "status", "description", "amount_usd", "tax_usd", "issued", "paid_at"],
      invoices.map((inv) => [
        String(inv.number).padStart(5, "0"),
        inv.user.name,
        inv.user.email,
        inv.status,
        inv.description,
        money(inv.amountCents),
        money(inv.taxCents),
        inv.createdAt.toISOString(),
        inv.paidAt ? inv.paidAt.toISOString() : "",
      ])
    );

    return new NextResponse(csv, {
      status: 200,
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="nxeon-invoices-${stamp}.csv"`,
        "Cache-Control": "private, no-store",
      },
    });
  }

  return NextResponse.json({ error: "unknown export type; use ?type=users|invoices" }, { status: 400 });
}

import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatCard, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { InvoiceStatusBadge } from "@/components/customer/InvoiceViews";
import { RegenerateMissingButton } from "@/components/admin/InvoiceAdmin";
import { BulkTable, type BulkRow } from "@/components/admin/BulkTable";
import { bulkVoidInvoices } from "@/lib/actions-admin-billing";
import { paginate, pageHref } from "@/lib/pagination";
import type { InvoiceStatus } from "@prisma/client";

export const dynamic = "force-dynamic";

const STATUSES: InvoiceStatus[] = ["OPEN", "PAID", "VOID", "REFUNDED"];
const PER_PAGE = 25;

export default async function AdminInvoices({
  searchParams,
}: {
  searchParams: Promise<{ status?: string; page?: string }>;
}) {
  await requireArea("billing");
  const sp = await searchParams;
  const status = STATUSES.includes(sp.status as InvoiceStatus)
    ? (sp.status as InvoiceStatus)
    : undefined;
  const where = status ? { status } : {};

  const [total, issued, paid, outstanding] = await Promise.all([
    db.invoice.count({ where }),
    db.invoice.aggregate({ where: { status: { not: "VOID" } }, _sum: { amountCents: true } }),
    db.invoice.aggregate({ where: { status: "PAID" }, _sum: { amountCents: true } }),
    db.invoice.aggregate({ where: { status: "OPEN" }, _sum: { amountCents: true } }),
  ]);

  const pg = paginate(sp, total, PER_PAGE);
  const invoices = await db.invoice.findMany({
    where,
    include: { user: { select: { id: true, email: true, name: true } } },
    orderBy: { createdAt: "desc" },
    skip: pg.skip,
    take: pg.take,
  });

  const chip = (href: string, label: string, active: boolean) => (
    <Link
      href={href}
      className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
        active
          ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
          : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
      }`}
    >
      {label}
    </Link>
  );

  const exportHref = `/api/admin/export?type=invoices${status ? `&status=${status}` : ""}`;
  const filterParams = { status };

  const rows: BulkRow[] = invoices.map((inv) => ({
    id: inv.id,
    // Only OPEN/REFUNDED invoices can be bulk-voided.
    selectable: inv.status === "OPEN" || inv.status === "REFUNDED",
    cells: [
      <Link key="n" href={`/admin/invoices/${inv.id}`} className="font-mono text-xs text-slate-300 hover:text-brand-300">
        #{String(inv.number).padStart(5, "0")}
      </Link>,
      <Link key="c" href={`/admin/users/${inv.user.id}`} className="hover:text-brand-300">
        {inv.user.email}
      </Link>,
      <Link key="d" href={`/admin/invoices/${inv.id}`} className="block max-w-xs truncate hover:text-brand-300">
        {inv.description}
      </Link>,
      <InvoiceStatusBadge key="s" status={inv.status} />,
      <span key="a" className="font-mono">{fmtMoney(inv.amountCents)}</span>,
      <span key="t" className="text-xs text-slate-400" title={inv.createdAt.toISOString()}>
        {timeAgo(inv.createdAt)}
      </span>,
    ],
  }));

  return (
    <div className="space-y-6">
      <PageHeader title="Invoices" sub="All billing documents issued across the platform.">
        <Link href="/admin/billing" className="btn-ghost py-1.5">
          Billing
        </Link>
        <RegenerateMissingButton />
      </PageHeader>

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Issued · total" value={fmtMoney(issued._sum.amountCents ?? 0)} delta="excl. void" />
        <StatCard label="Paid" value={fmtMoney(paid._sum.amountCents ?? 0)} />
        <StatCard label="Outstanding" value={fmtMoney(outstanding._sum.amountCents ?? 0)} delta="open" deltaGood={false} />
        <StatCard label="Count" value={String(total)} delta={status ? `filtered: ${status.toLowerCase()}` : "all statuses"} />
      </div>

      <div className="card p-0">
        <div className="flex flex-wrap items-center justify-end gap-2 px-5 pt-5">
          {chip("/admin/invoices", "All", !status)}
          {STATUSES.map((s) =>
            chip(`/admin/invoices?status=${s}`, s.charAt(0) + s.slice(1).toLowerCase(), status === s)
          )}
        </div>

        <BulkTable
          columns={[
            { header: "Number" },
            { header: "Client" },
            { header: "Description" },
            { header: "Status" },
            { header: "Amount", className: "text-right" },
            { header: "Issued", className: "text-right" },
          ]}
          rows={rows}
          exportHref={exportHref}
          minWidth={760}
          empty="No invoices found."
          actions={[
            {
              label: "Void",
              danger: true,
              confirm: "Void the selected open invoices? They will no longer be collectible.",
              run: bulkVoidInvoices,
            },
          ]}
        />

        <div className="flex items-center justify-between gap-3 px-5 py-4 text-xs text-slate-500">
          <span>
            Page {pg.page} of {pg.pages} · {total} invoice{total === 1 ? "" : "s"}
          </span>
          <div className="flex items-center gap-2">
            {pg.page > 1 && (
              <Link href={pageHref("/admin/invoices", filterParams, pg.page - 1)} className="btn-ghost py-1 text-xs">
                ← Prev
              </Link>
            )}
            {pg.page < pg.pages && (
              <Link href={pageHref("/admin/invoices", filterParams, pg.page + 1)} className="btn-ghost py-1 text-xs">
                Next →
              </Link>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { SuspendUserButton } from "@/components/AdminControls";
import { ImpersonateButton } from "@/components/admin/ImpersonateButton";
import { BulkTable, type BulkRow } from "@/components/admin/BulkTable";
import { bulkSuspendUsers } from "@/lib/actions-admin-billing";
import { paginate, pageHref } from "@/lib/pagination";

export const dynamic = "force-dynamic";

const PER_PAGE = 25;

export default async function AdminUsers({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; page?: string }>;
}) {
  await requireArea("clients");
  const sp = await searchParams;
  const query = (sp.q ?? "").trim();

  const where = query
    ? {
        OR: [
          { email: { contains: query, mode: "insensitive" as const } },
          { name: { contains: query, mode: "insensitive" as const } },
        ],
      }
    : undefined;

  const total = await db.user.count({ where });
  const pg = paginate(sp, total, PER_PAGE);
  const users = await db.user.findMany({
    where,
    include: {
      servers: {
        where: { status: { notIn: ["DELETING"] } },
        select: { isFree: true, plan: { select: { priceCents: true } } },
      },
    },
    orderBy: { createdAt: "desc" },
    skip: pg.skip,
    take: pg.take,
  });

  const exportHref = `/api/admin/export?type=users${query ? `&q=${encodeURIComponent(query)}` : ""}`;

  const rows: BulkRow[] = users.map((u) => {
    const mrr = u.servers.reduce((n, s) => n + (s.isFree ? 0 : s.plan.priceCents), 0);
    return {
      id: u.id,
      selectable: u.role !== "ADMIN",
      cells: [
        <span key="c">
          <Link href={`/admin/users/${u.id}`} className="font-medium hover:text-brand-300">
            {u.name}
          </Link>
          <span className="ml-2 text-xs text-slate-500">{u.email}</span>
          {u.suspended && (
            <span className="ml-2">
              <Badge tone="red">suspended</Badge>
            </span>
          )}
        </span>,
        <Badge key="r" tone={u.role === "ADMIN" ? "brand" : "slate"}>{u.role.toLowerCase()}</Badge>,
        u.servers.length,
        fmtMoney(u.balanceCents),
        mrr > 0 ? `${fmtMoney(mrr)}/mo` : <span key="m" className="text-slate-500">—</span>,
        <span key="j" className="text-xs text-slate-400">{timeAgo(u.createdAt)}</span>,
        <div key="a" className="flex items-center justify-end gap-2">
          <Link href={`/admin/users/${u.id}`} className="btn-ghost py-1 text-xs">
            View →
          </Link>
          {u.role !== "ADMIN" && <ImpersonateButton userId={u.id} email={u.email} small />}
          {u.role !== "ADMIN" && <SuspendUserButton userId={u.id} suspended={u.suspended} />}
        </div>,
      ],
    };
  });

  return (
    <div className="space-y-6">
      <PageHeader title="Clients" sub={`${total} account${total === 1 ? "" : "s"}${query ? ` matching “${query}”` : ""}`}>
        <form method="GET" className="flex items-center gap-2">
          <input
            className="input w-64 py-2"
            type="search"
            name="q"
            placeholder="Search email or name…"
            defaultValue={query}
          />
          <button className="btn-secondary py-2">Search</button>
          {query && (
            <Link href="/admin/users" className="btn-ghost py-2 text-xs">
              Clear
            </Link>
          )}
        </form>
      </PageHeader>

      <div className="card p-0">
        <BulkTable
          columns={[
            { header: "Client" },
            { header: "Role" },
            { header: "Servers" },
            { header: "Balance" },
            { header: "Monthly spend" },
            { header: "Joined" },
            { header: "Actions", className: "text-right" },
          ]}
          rows={rows}
          exportHref={exportHref}
          minWidth={860}
          empty="No clients match this search."
          actions={[
            {
              label: "Suspend",
              danger: true,
              confirm: "Suspend the selected clients?",
              run: bulkSuspendUsers,
            },
          ]}
        />

        <div className="flex items-center justify-between gap-3 px-5 py-4 text-xs text-slate-500">
          <span>
            Page {pg.page} of {pg.pages} · {total} client{total === 1 ? "" : "s"}
          </span>
          <div className="flex items-center gap-2">
            {pg.page > 1 && (
              <Link href={pageHref("/admin/users", { q: query }, pg.page - 1)} className="btn-ghost py-1 text-xs">
                ← Prev
              </Link>
            )}
            {pg.page < pg.pages && (
              <Link href={pageHref("/admin/users", { q: query }, pg.page + 1)} className="btn-ghost py-1 text-xs">
                Next →
              </Link>
            )}
          </div>
        </div>
      </div>

      <p className="text-xs text-slate-500">
        Wallet credits are issued from a client&apos;s profile page. Monthly spend is the committed MRR of the
        client&apos;s active paid servers. Select rows to bulk-suspend or export the filtered set to CSV.
      </p>
    </div>
  );
}

